from typing import Optional

from fastapi import Body, Depends, FastAPI, HTTPException, Query
from fastapi.encoders import jsonable_encoder

from app.models import ItemIn, ItemOut, Page
from app.settings import load_settings
from app.store import Store

settings = load_settings()
app = FastAPI(title=settings.app_name)
store = Store()

SEED = [
    {"sku": "ABC-001", "name": "blue mug", "price": 7.5, "tags": ["kitchen"], "note": None},
    {"sku": "ABC-002", "name": "red  mug", "price": 8.0, "discount": 1.0,
     "tags": ["kitchen", "sale"], "note": "last ones"},
]
EXAMPLE = {"sku": "XYZ-123", "name": "pen", "price": 1.2, "tags": ["office"]}


@app.on_event("startup")
def seed_store():
    store.clear()
    for row in SEED:
        store.add(ItemIn(**row).dict())


def get_store():
    return store


@app.get("/items", response_model=Page)
def list_items(tag: Optional[str] = Query(None, regex=r"^[a-z]+$"),
               s: Store = Depends(get_store)):
    rows = s.find(tag)
    return Page(items=[ItemOut.from_orm(r) for r in rows], total=len(rows))


@app.get("/items/{sku}", response_model=ItemOut)
def read_item(sku: str, s: Store = Depends(get_store)):
    rec = s.get(sku)
    if rec is None:
        raise HTTPException(status_code=404, detail="no such item")
    return ItemOut.from_orm(rec)


@app.post("/items", response_model=ItemOut, status_code=201)
def create_item(item: ItemIn = Body(..., example=EXAMPLE), s: Store = Depends(get_store)):
    if s.get(item.sku):
        raise HTTPException(status_code=409, detail="exists")
    rec = s.add(item.dict())
    return ItemOut.from_orm(rec)


@app.get("/summary")
def summary(s: Store = Depends(get_store)):
    rows = s.find()
    value = round(sum(r.net for r in rows), 2)
    return jsonable_encoder({"count": len(rows), "value": value, "currency": settings.currency})

