from typing import List, Optional

from pydantic import BaseModel, Field, conlist, root_validator, validator

SKU = r"^[A-Z]{3}-\d{3}$"


class ItemIn(BaseModel):
    sku: str = Field(..., regex=SKU)
    name: str
    price: float = Field(..., gt=0)
    discount: float = 0.0
    tags: conlist(str, min_items=1)
    note: Optional[str]

    @validator("name")
    def tidy_name(cls, v):
        return " ".join(v.split()).title()

    @root_validator
    def discount_below_price(cls, values):
        price, discount = values.get("price"), values.get("discount")
        if price is not None and discount >= price:
            raise ValueError("discount must be below price")
        return values


class ItemOut(BaseModel):
    sku: str
    name: str
    price: float
    discount: float
    tags: List[str]
    note: Optional[str] = None

    class Config:
        orm_mode = True


class Page(BaseModel):
    items: List[ItemOut]
    total: int

