"""In-memory storage: plain project code, no dependency calls."""
from dataclasses import dataclass, field
from typing import Dict, List, Optional


@dataclass
class Record:
    sku: str
    name: str
    price: float
    discount: float = 0.0
    tags: List[str] = field(default_factory=list)
    note: Optional[str] = None

    @property
    def net(self):
        return round(self.price - self.discount, 2)


class Store:
    def __init__(self):
        self._rows: Dict[str, Record] = {}

    def add(self, data):
        rec = Record(**data)
        self._rows[rec.sku] = rec
        return rec

    def get(self, sku):
        return self._rows.get(sku)

    def find(self, tag=None):
        rows = sorted(self._rows.values(), key=lambda r: r.sku)
        return [r for r in rows if tag is None or tag in r.tags]

    def clear(self):
        self._rows.clear()

